#define createPluginFilter createNamTestFilter
#include "../plugins/AvrxNam/Plugin.cpp"
#undef createPluginFilter
#include <iostream>
static void check(bool ok,const char* message){if(!ok){std::cerr<<"FAIL NAM: "<<message<<'\n';std::exit(1);}}
int main(int argc,char** argv){check(argc>2,"test folder and preview path");juce::ScopedJuceInitialiser_GUI gui;const juce::File folder(juce::String::fromUTF8(argv[1]));check(folder.createDirectory().wasOk(),"test folder");auto capture=folder.getChildFile("Linear.nam");check(capture.replaceWithText(R"({"version":"0.5.4","architecture":"Linear","sample_rate":48000,"config":{"receptive_field":1,"bias":false},"weights":[0.5]})"),"model fixture");NamProcessor processor;processor.prepareToPlay(48000,256);auto legacy=processor.parameters.copyState();legacy.setProperty("modelPath",capture.getFullPathName(),nullptr);juce::MemoryBlock bytes;juce::AudioProcessor::copyXmlToBinary(*legacy.createXml(),bytes);processor.setStateInformation(bytes.getData(),int(bytes.getSize()));juce::AudioBuffer<float> audio(2,256);juce::MidiBuffer midi;
 auto render=[&](double frequency){for(int n=0;n<256;++n){float value=.1f*float(std::sin(2*TracksmithEq::pi*frequency*n/48000));audio.setSample(0,n,value);audio.setSample(1,n,value);}processor.processBlock(audio,midi);};bool loaded=false;for(int i=0;i<100;++i){juce::Thread::sleep(20);juce::Timer::callPendingTimersSynchronously();render(1000);if(processor.status().startsWith("Loaded")){loaded=true;break;}}check(loaded,"load model");
 auto set=[&](const char* id,float value){auto* p=processor.parameters.getParameter(id);p->setValueNotifyingHost(p->convertTo0to1(value));};set("bass",6);set("mid",-4);set("treble",3);set("midfreq",1400);set("highpass",80);set("gate",1);auto preset=folder.getChildFile("Guitar.tsnampreset");check(processor.savePreset(preset).wasOk(),"save preset");set("bass",0);set("gate",0);check(processor.loadPreset(preset).wasOk(),"load preset");check(std::abs(processor.parameters.getRawParameterValue("bass")->load()-6)<.01&&processor.parameters.getRawParameterValue("gate")->load()>.5,"preset recalls EQ and gate");
 auto missing=folder.getChildFile("Missing.tsnampreset");auto xml=juce::XmlDocument::parse(preset);auto tree=juce::ValueTree::fromXml(*xml);tree.getChild(0).setProperty("modelPath",folder.getChildFile("missing.nam").getFullPathName(),nullptr);tree.setProperty("modelRelative","missing.nam",nullptr);check(missing.replaceWithText(tree.createXml()->toString()),"missing preset fixture");check(processor.loadPreset(missing).failed(),"missing model rejected");check(std::abs(processor.parameters.getRawParameterValue("bass")->load()-6)<.01,"failed preset keeps settings");
 auto invalid=folder.getChildFile("Invalid.tsnampreset");invalid.replaceWithText("bad xml");check(processor.loadPreset(invalid).failed(),"malformed preset rejected");
 auto moved=folder.getChildFile("Moved");check(moved.createDirectory().wasOk(),"moved folder");check(capture.copyFileTo(moved.getChildFile("Linear.nam")),"copy model beside preset");auto relative=juce::ValueTree::fromXml(*juce::XmlDocument::parse(preset));relative.getChild(0).setProperty("modelPath",folder.getChildFile("old-location.nam").getFullPathName(),nullptr);relative.setProperty("modelRelative","Linear.nam",nullptr);auto movedPreset=moved.getChildFile("Moved.tsnampreset");movedPreset.replaceWithText(relative.createXml()->toString());juce::ValueTree recalled;check(NamPresets::load(movedPreset,recalled).wasOk()&&recalled.getProperty("modelPath").toString()==moved.getChildFile("Linear.nam").getFullPathName(),"relative model fallback");relative.getChild(0).getChild(0).setProperty("value","NaN",nullptr);movedPreset.replaceWithText(relative.createXml()->toString());check(NamPresets::load(movedPreset,recalled).failed(),"nonfinite preset rejected");check(processor.savePreset(preset).wasOk(),"atomic preset overwrite");
 // Old sessions have no EQ children and must restore a neutral EQ.
 for(int i=legacy.getNumChildren();--i>=0;){auto id=legacy.getChild(i).getProperty("id").toString();if(id=="bass"||id=="mid"||id=="treble"||id=="midfreq"||id=="highpass"||id=="eq")legacy.removeChild(i,nullptr);}juce::AudioProcessor::copyXmlToBinary(*legacy.createXml(),bytes);processor.setStateInformation(bytes.getData(),int(bytes.getSize()));check(processor.parameters.getRawParameterValue("bass")->load()==0&&processor.parameters.getRawParameterValue("highpass")->load()==20,"legacy state restores flat EQ");
 set("mid",6);set("midfreq",1000);set("gate",0);double inputEnergy=0,outputEnergy=0;for(int b=0;b<500;++b){for(int n=0;n<256;++n){float v=.1f*float(std::sin(2*TracksmithEq::pi*1000*(b*256+n)/48000));audio.setSample(0,n,v);audio.setSample(1,n,v);if(b>450)inputEnergy+=v*v;}processor.processBlock(audio,midi);if(b>450)for(int n=0;n<256;++n)outputEnergy+=audio.getSample(0,n)*audio.getSample(0,n);}check(std::abs(10*std::log10(outputEnergy/inputEnergy))<.1,"post-model EQ boosts linear 0.5 model by 6dB");
 set("mid",0);NamProcessor preview;preview.prepareToPlay(48000,256);std::unique_ptr<juce::AudioProcessorEditor> editor(preview.createEditorIfNeeded());editor->setVisible(true);juce::Image image(juce::Image::ARGB,editor->getWidth(),editor->getHeight(),true);{juce::Graphics g(image);editor->paintEntireComponent(g,true);}juce::FileOutputStream stream(juce::File(juce::String::fromUTF8(argv[2])));stream.setPosition(0);juce::PNGImageFormat png;check(png.writeImageToStream(image,stream),"native editor render");stream.truncate();std::cout<<"PASS: NAM model load, EQ audio gain, preset file save/recall, missing/malformed presets preserve settings, legacy flat EQ restore and editor render\n";return 0;}

